'use client';
import { useState, useRef, useEffect } from 'react';
import ReactMarkdown from 'react-markdown';

interface Mensaje {
  role: 'estudiante' | 'profesor';
  texto: string;
}

export default function AulaVirtual() {
  const [mensajes, setMensajes] = useState<Mensaje[]>([]);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const [asignatura, setAsignatura] = useState('Matemáticas');
  const scrollRef = useRef<HTMLDivElement>(null);
  const [isMounted, setIsMounted] = useState(false);

  const nivelEducativo = "Secundaria";

  // Cargar mensajes desde localStorage al montar
  useEffect(() => {
    setIsMounted(true);
    const saved = localStorage.getItem('chatHistory');
    if (saved) {
      setMensajes(JSON.parse(saved));
    }
  }, []);

  // Guardar mensajes en localStorage cuando cambian
  useEffect(() => {
    if (isMounted) {
      localStorage.setItem('chatHistory', JSON.stringify(mensajes));
    }
  }, [mensajes, isMounted]);

  // Efecto para auto-scroll al recibir mensajes
  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [mensajes, loading]);

  const enviarMensaje = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!input.trim()) return;

    const nuevoMensaje: Mensaje = { role: 'estudiante', texto: input };
    const historialActualizado = [...mensajes, nuevoMensaje];
    
    setMensajes(historialActualizado);
    setInput('');
    setLoading(true);

    try {
      const res = await fetch('/api/profesor', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          preguntaEstudiante: input,
          asignatura, // Se envía el estado actual
          nivelEducativo,
          historialConversacion: mensajes,
        }),
      });

      const data = await res.json();
      
      if (!res.ok) throw new Error(data.error || 'Error');

      setMensajes([...historialActualizado, { role: 'profesor', texto: data.respuesta }]);
    } catch (error: any) {
      setMensajes([...historialActualizado, { role: 'profesor', texto: error.message }]);
    } finally {
      setLoading(false);
    }
  };

  if (!isMounted) return null;

  return (
    <div className="flex flex-col min-h-screen bg-gray-50">
      <header className="bg-blue-600 text-white p-4 shadow-md sticky top-0 z-10 flex justify-between items-center">
        <div className="flex items-center gap-4">
          <div>
            <h1 className="text-xl font-bold">Aula Virtual</h1>
            <p className="text-xs opacity-90">{nivelEducativo}</p>
          </div>
          <select 
            value={asignatura}
            onChange={(e) => setAsignatura(e.target.value)}
            className="bg-blue-700 text-white text-sm rounded p-1 border-none focus:ring-2 focus:ring-white"
          >
            <option>Matemáticas</option>
            <option>Historia</option>
            <option>Ciencias</option>
            <option>Literatura</option>
          </select>
        </div>
        <button 
          onClick={() => { setMensajes([]); localStorage.removeItem('chatHistory'); }}
          className="text-xs bg-red-500 hover:bg-red-600 px-3 py-1 rounded"
        >
          Limpiar
        </button>
      </header>

      <main 
        ref={scrollRef}
        className="flex-1 overflow-y-auto p-4 space-y-4 mb-20 scroll-smooth"
      >
        {mensajes.length === 0 && (
          <div className="text-center text-gray-400 mt-20">
            ¡Hola! Soy tu profesor de {asignatura}. ¿En qué puedo ayudarte hoy?
          </div>
        )}
        {mensajes.map((msg, i) => (
          <div key={i} className={`flex ${msg.role === 'estudiante' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[80%] p-3 rounded-lg ${
              msg.role === 'estudiante' 
                ? 'bg-blue-500 text-white rounded-br-none' 
                : 'bg-white border border-gray-200 text-gray-800 rounded-bl-none shadow-sm prose prose-sm'
            }`}>
              {msg.role === 'profesor' ? (
                <ReactMarkdown>{msg.texto}</ReactMarkdown>
              ) : (
                msg.texto
              )}
            </div>
          </div>
        ))}
        {loading && (
          <div className="flex justify-start">
            <div className="bg-white p-3 rounded-lg animate-pulse text-gray-500 border border-gray-200">
              Escribiendo respuesta...
            </div>
          </div>
        )}
      </main>

      <form onSubmit={enviarMensaje} className="fixed bottom-0 w-full p-4 bg-white border-t flex gap-2">
        <input
          value={input}
          onChange={(e) => setInput(e.target.value)}
          disabled={loading}
          className="flex-1 border rounded-lg p-2 focus:outline-none focus:ring-2 focus:ring-blue-500"
          placeholder={`Pregunta sobre ${asignatura}...`}
        />
        <button 
          disabled={loading}
          className="bg-blue-600 text-white px-6 py-2 rounded-lg font-semibold disabled:bg-gray-400"
        >
          {loading ? '...' : 'Enviar'}
        </button>
      </form>
    </div>
  );
}
